<script setup lang="ts">
import {knowledgeAvailable} from '../services/clientCapabilities'
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute,useRouter,onBeforeRouteLeave } from 'vue-router'
import {ElDialog,ElButton,ElProgress,ElAlert} from 'element-plus'
import 'element-plus/es/components/dialog/style/css'
import 'element-plus/es/components/button/style/css'
import 'element-plus/es/components/progress/style/css'
import 'element-plus/es/components/alert/style/css'
import type { NoteEntity,NoteOrganizationStatus,NoteType } from '@note-flow/core'
import { useAuthStore } from '../stores/auth'
import { useNotesStore } from '../stores/notes'
import { createGovernanceService,issuesFor,pathMatches,type GovernanceBatch,type GovernanceIssue,type GovernanceItem,type GovernanceRole,type GovernanceRule,type GovernanceSourceNode,type TaskCandidate } from '../services/governance'
import { tasksService,taskNotesService } from '../services/tasks'
import { workspaceService,type AreaEntity,type ProjectEntity } from '../services/workspace'
import { noteOrganizationService } from '../services/noteOrganization'
import { confirmDialog as productConfirmDialog,promptDialog } from '../services/productDialog'
import { AI_DATA_CONFIRMATION,AI_KNOWLEDGE_CONFIRMATION,AI_UNAVAILABLE_MESSAGE } from '../services/aiExperience'
import { attachmentLibrary,type LibraryAttachment } from '../services/attachments'
import { findMarkdownImages } from '../services/attachmentReferences'
import { convertRemoteImages,convertRemoteImagesOnServer,scanRemoteImages,REMOTE_IMAGE_BATCH_LIMIT,type RemoteImageGovernanceResult } from '../services/remoteImageGovernance'
import {isDesktopClient} from '../services/serverConfig'
import { knowledgeService,type KnowledgeEntity } from '../services/knowledge'
import { globalAreaUid } from '../services/globalAreaScope'

const auth=useAuthStore(),notesStore=useNotesStore(),router=useRouter(),route=useRoute()
const service=computed(()=>createGovernanceService(auth.user?.userId||''))
const items=ref<GovernanceItem[]>([]),candidates=ref<TaskCandidate[]>([]),rules=ref<GovernanceRule[]>([]),batches=ref<GovernanceBatch[]>([])
const sourceNodes=ref<GovernanceSourceNode[]>([]),areas=ref<AreaEntity[]>([]),projects=ref<ProjectEntity[]>([])
const knowledgeItems=ref<KnowledgeEntity[]>([])
const selected=ref<string[]>([]),queue=ref<'all'|GovernanceIssue|'source'>('pending'),sourceDir=ref(''),query=ref(''),busy=ref(false),message=ref(''),tab=ref<'workbench'|'rules'|'quality'|'resources'|'history'>('workbench')
const notePageSize=50,visibleNoteLimit=ref(notePageSize)
const resourceQuery=ref(''),resourceHost=ref(''),resourceSelected=ref(new Set<string>()),resourceBusy=ref(false),resourceProgress=ref({completed:0,total:0}),resourceResult=ref<RemoteImageGovernanceResult>()
const resourceDialogOpen=ref(false),resourcePhase=ref<'confirm'|'running'|'finished'|'error'>('confirm'),resourceStage=ref(''),resourceError=ref('')
const resourcePlanned=ref(new Set<string>())
const resourcePercent=computed(()=>Math.min(resourceBusy.value?99:100,Math.round(resourceProgress.value.total?resourceProgress.value.completed/resourceProgress.value.total*100:0)))
onBeforeRouteLeave(()=>!resourceBusy.value)
const collapsedSourceDirs=ref(new Set<string>())
const directoryPreviewOpen=ref(false),directoryExecutionApproved=ref(false),directoryProgress=ref({running:false,percent:0,stage:'',processed:0,total:0,error:''})
const directoryPreviewLoading=ref(false),directoryPreviewAttachments=ref<LibraryAttachment[]>([])
const confirmDialog=(options:Parameters<typeof productConfirmDialog>[0])=>{if(directoryExecutionApproved.value){directoryExecutionApproved.value=false;return Promise.resolve(true)}return productConfirmDialog(options)}
const ruleDraft=ref({name:'',pathPattern:'**',role:'knowledge' as GovernanceRole,noteType:'' as NoteType|'',status:'organized' as NoteOrganizationStatus,autoRun:false})
const nodeDraft=ref({role:'unclassified' as GovernanceRole,areaUid:'',projectUid:'',childStrategy:'none' as GovernanceSourceNode['childStrategy'],journalPattern:'工作日志'})
const roleLabels:Record<GovernanceRole,string>={unclassified:'未分类',project_collection:'项目集合',project:'项目',area:'领域',knowledge:'知识目录',journal:'日记',task_list:'任务清单',inbox:'收集箱',private:'私密',ignore:'忽略'}
const noteTypeLabels:Record<NoteType,string>={note:'普通笔记',mindmap:'思维导图',file:'文件',knowledge:'知识笔记',meeting:'会议记录',work_log:'工作日志',problem_analysis:'问题分析',journal:'日记与报告'}
const scopedNotes=computed(()=>notesStore.notes.filter(note=>!globalAreaUid.value||note.areaUid===globalAreaUid.value))
const issueLabels:Record<GovernanceIssue,string>={pending:'待治理',unclassified:'未分类',missing_area:'无领域',missing_project:'无项目',missing_folder:'无目录',missing_tags:'无标签',task_candidates:'任务候选',duplicate_title:'疑似重复',stale:'长期未更新'}
const itemMap=computed(()=>new Map(items.value.map(value=>[value.noteUid,value])))
const sourceNodeMap=computed(()=>new Map(sourceNodes.value.map(value=>[value.path,value])))
const candidateCount=computed(()=>{const map=new Map<string,number>();for(const value of candidates.value)if(value.state==='pending')map.set(value.noteUid,(map.get(value.noteUid)||0)+1);return map})
const titleCount=computed(()=>{const map=new Map<string,number>();for(const note of scopedNotes.value){const key=(note.title||'').trim().toLocaleLowerCase();if(key)map.set(key,(map.get(key)||0)+1)}return map})
const noteIssues=(note:NoteEntity)=>issuesFor(note,itemMap.value.get(note.uid),candidateCount.value.get(note.uid)||0,titleCount.value.get((note.title||'').trim().toLocaleLowerCase())||1)
const sourceDirs=computed(()=>{const counts=new Map<string,number>();for(const value of items.value){if(!value.sourceDir)continue;const parts=value.sourceDir.split('/');for(let i=1;i<=parts.length;i++){const path=parts.slice(0,i).join('/');counts.set(path,(counts.get(path)||0)+1)}}return [...counts].map(([path,count])=>({path,count,depth:path.split('/').length-1})).sort((a,b)=>a.path.localeCompare(b.path,'zh-CN'))})
const visibleSourceDirs=computed(()=>sourceDirs.value.filter(dir=>{const parts=dir.path.split('/');return !parts.slice(0,-1).some((_part,index)=>collapsedSourceDirs.value.has(parts.slice(0,index+1).join('/')))}))
const sourceDirHasChildren=(path:string)=>sourceDirs.value.some(value=>value.path.startsWith(`${path}/`))
const filteredNotes=computed(()=>scopedNotes.value.filter(note=>{const text=`${note.title} ${itemMap.value.get(note.uid)?.sourcePath||''}`.toLocaleLowerCase();if(query.value&&!text.includes(query.value.toLocaleLowerCase()))return false;if(queue.value==='source')return Boolean(sourceDir.value&&itemMap.value.get(note.uid)?.sourcePath?.startsWith(sourceDir.value));if(queue.value==='all')return true;return noteIssues(note).includes(queue.value)}))
const visibleNotes=computed(()=>filteredNotes.value.slice(0,visibleNoteLimit.value))
const displayedNotes=visibleNotes
const hasMoreVisibleNotes=computed(()=>visibleNotes.value.length<filteredNotes.value.length)
function loadMoreVisibleNotes(){visibleNoteLimit.value+=notePageSize}
const activeNote=computed(()=>scopedNotes.value.find(note=>note.uid===selected.value.at(-1))||visibleNotes.value[0])
const activeCandidates=computed(()=>candidates.value.filter(value=>value.noteUid===activeNote.value?.uid&&value.state==='pending'))
const issueMetrics=computed(()=>(Object.keys(issueLabels) as GovernanceIssue[]).map(issue=>({issue,label:issueLabels[issue],count:scopedNotes.value.filter(note=>noteIssues(note).includes(issue)).length})))
const qualityMetrics=computed(()=>issueMetrics.value.filter(value=>value.issue!=='pending'))
const qualityScore=computed(()=>{if(!scopedNotes.value.length)return 100;const clean=scopedNotes.value.filter(note=>!noteIssues(note).some(issue=>issue!=='pending')).length;return Math.round(clean/scopedNotes.value.length*100)})
const qualityReason:Record<GovernanceIssue,string>={pending:'笔记尚未完成治理流程。',unclassified:'笔记既没有明确的内容角色，也没有类型、目录、领域或项目归属。',missing_area:'笔记未归属长期责任领域。',missing_project:'笔记未关联阶段性项目。',missing_folder:'笔记没有可浏览的目录位置。',missing_tags:'笔记缺少主题标签，检索复用困难。',task_candidates:'正文含有尚未确认的 Markdown Checklist。',duplicate_title:'存在同名笔记，需要进一步进行内容相似度复核。',stale:'超过 180 天没有更新，建议确认是否仍然有效。'}
const previewRule=(rule:GovernanceRule)=>notesStore.notes.filter(note=>{const item=itemMap.value.get(note.uid);return item?.sourcePath&&(!rule.sourceRoot||item.sourceRoot===rule.sourceRoot)&&pathMatches(item.sourcePath,rule.pathPattern)})
const remoteImages=computed(()=>scanRemoteImages(scopedNotes.value,knowledgeItems.value.filter(item=>!globalAreaUid.value||item.areaUid===globalAreaUid.value)))
const remoteHosts=computed(()=>[...new Set(remoteImages.value.map(value=>value.host))].sort())
const filteredRemoteImages=computed(()=>remoteImages.value.filter(value=>(!resourceHost.value||value.host===resourceHost.value)&&(!resourceQuery.value||`${value.entityTitle} ${value.entityType} ${value.url} ${value.entityType==='note'?itemMap.value.get(value.entityUid)?.sourcePath||'':''}`.toLocaleLowerCase().includes(resourceQuery.value.toLocaleLowerCase()))))
const remoteBatchCandidates=computed(()=>filteredRemoteImages.value.slice(0,REMOTE_IMAGE_BATCH_LIMIT))
const remoteBatchSelected=computed(()=>remoteBatchCandidates.value.length>0&&remoteBatchCandidates.value.every(value=>resourceSelected.value.has(value.uid)))
function toggleRemote(uid:string,checked:boolean){if(resourceBusy.value)return;if(checked&&resourceSelected.value.size>=REMOTE_IMAGE_BATCH_LIMIT){message.value=`每批最多选择 ${REMOTE_IMAGE_BATCH_LIMIT} 条，请先转换当前批次。`;return}const next=new Set(resourceSelected.value);checked?next.add(uid):next.delete(uid);resourceSelected.value=next}
function selectRemoteVisible(){if(resourceBusy.value)return;resourceSelected.value=remoteBatchSelected.value?new Set():new Set(remoteBatchCandidates.value.map(value=>value.uid))}
function retryRemoteFailures(){const failed=resourceResult.value?.failures||[],next=new Set<string>();for(const candidate of remoteImages.value)if(failed.some(value=>value.entityType===candidate.entityType&&value.entityUid===candidate.entityUid&&value.url===candidate.url))next.add(candidate.uid);resourceSelected.value=next;resourceResult.value=undefined}
function executeRemoteGovernance(){
 if(!resourceSelected.value.size||resourceBusy.value||resourceDialogOpen.value)return
 resourcePlanned.value=new Set(resourceSelected.value);resourceResult.value=undefined;resourceError.value='';resourceProgress.value={completed:0,total:resourcePlanned.value.size};resourceStage.value='';resourcePhase.value='confirm';resourceDialogOpen.value=true
}
async function startRemoteGovernance(){
 if(resourceBusy.value||resourcePhase.value!=='confirm')return
 resourceBusy.value=true;resourcePhase.value='running';resourceStage.value='正在提交转换请求…'
 let offline=false,requestStarted=false
 try{
  const before=new Map(notesStore.notes.map(note=>[note.uid,note.content])),selected=remoteImages.value.filter(value=>resourcePlanned.value.has(value.uid))
  if(!selected.length)throw new Error('所选图片引用已变化，请关闭窗口后重新选择。')
  if(selected.length>REMOTE_IMAGE_BATCH_LIMIT)throw new Error(`每批最多转换 ${REMOTE_IMAGE_BATCH_LIMIT} 条，请关闭窗口并使用“选择前${REMOTE_IMAGE_BATCH_LIMIT}条”。`)
  resourceProgress.value.total=selected.length
  const progress=(completed:number,total:number,status?:string)=>{resourceProgress.value={completed,total};resourceStage.value=status==='queued'?'服务器已接收，正在排队…':status==='completed'||status==='partial'||status==='failed'?'转换已结束，正在读取结果…':'正在下载图片、保存附件并更新正文…'}
  offline=isDesktopClient()&&navigator.onLine===false
  resourceStage.value=offline?'正在下载图片并写入本地附件队列…':'正在提交转换请求…';requestStarted=true
  const result=offline?await convertRemoteImages(auth.user?.userId||'',notesStore.notes,new Set(selected.map(value=>value.uid)),(note,content)=>notesStore.updateEntity(note,{content}),progress,knowledgeItems.value,async(value,content)=>{const saved=await knowledgeService.update({...value,content},'离线固化远程图片为知识附件'),index=knowledgeItems.value.findIndex(item=>item.uid===saved.uid);if(index>=0)knowledgeItems.value[index]=saved;return saved}):await convertRemoteImagesOnServer(selected,progress)
  resourceResult.value=result;resourceSelected.value=new Set();resourceStage.value='正在刷新内容和保存治理记录…'
  if(!offline){await notesStore.load();knowledgeItems.value=knowledgeAvailable?await knowledgeService.list('', '', globalAreaUid.value):[]}
  const changed=notesStore.notes.filter(note=>before.get(note.uid)!==note.content).map(note=>({noteUid:note.uid,before:{content:before.get(note.uid)||''},after:{content:note.content}}))
  if(changed.length)await service.value.recordBatch('外链图片转为私有附件',changed)
  batches.value=await service.value.batches();resourcePhase.value='finished';resourceStage.value=result.failed?'转换结束，部分图片未成功':'转换完成'
  message.value=`外链资源治理完成：成功 ${result.converted}，失败 ${result.failed}；更新内容 ${result.updatedNotes+result.updatedKnowledge}`
  window.dispatchEvent(new Event('note-flow:workspace-change'))
 }catch(source){
  const reason=source instanceof Error?source.message:typeof source==='string'?source:'发生未知错误，请检查网络或服务器状态。'
  resourceError.value=resourceResult.value?`转换结果已返回，但刷新内容或保存治理记录失败：${reason}。请刷新内容后核对，避免重复转换。`:`${reason}${!offline&&requestStarted?'。如果服务器已经接收任务，转换可能仍在执行；请先刷新核对结果，避免重复提交。':''}`
  resourcePhase.value='error';resourceStage.value=resourceResult.value?'转换结果已返回，后续处理失败':'暂时无法确认转换结果';message.value=resourceError.value
 }finally{resourceBusy.value=false}
}

async function reload(backfill=false){busy.value=true;message.value='';try{await notesStore.load();knowledgeItems.value=knowledgeAvailable?await knowledgeService.list():[];if(backfill)await service.value.backfill(notesStore.notes);[items.value,candidates.value,rules.value,batches.value,sourceNodes.value,areas.value,projects.value]=await Promise.all([service.value.items(),service.value.candidates(),service.value.rules(),service.value.batches(),service.value.sourceNodes(),workspaceService.areas(),workspaceService.projects(undefined,true)])}catch(source){message.value=source instanceof Error?source.message:'治理数据加载失败'}finally{busy.value=false}}
function choose(uid:string,event?:MouseEvent){if(event?.ctrlKey||event?.metaKey){selected.value=selected.value.includes(uid)?selected.value.filter(value=>value!==uid):[...selected.value,uid]}else selected.value=[uid]}
function selectVisible(){selected.value=selected.value.length===visibleNotes.value.length?[]:visibleNotes.value.map(note=>note.uid)}
function toggleSourceDir(path:string){const next=new Set(collapsedSourceDirs.value);next.has(path)?next.delete(path):next.add(path);collapsedSourceDirs.value=next}
function selectSourceDirectory(path:string){queue.value='source';sourceDir.value=path;selected.value=[];const node=sourceNodeMap.value.get(path);nodeDraft.value=node?{role:node.role,areaUid:node.areaUid||'',projectUid:node.projectUid||'',childStrategy:node.childStrategy,journalPattern:node.journalPattern}:{role:'unclassified',areaUid:'',projectUid:'',childStrategy:'none',journalPattern:'工作日志'}}
const directSourceChildren=computed(()=>{if(!sourceDir.value)return[];const children=new Map<string,number>();for(const item of items.value){const path=item.sourcePath||'';if(!path.startsWith(`${sourceDir.value}/`))continue;const relative=path.slice(sourceDir.value.length+1),parts=relative.split('/').filter(Boolean);if(parts.length<2)continue;const child=`${sourceDir.value}/${parts[0]}`;children.set(child,(children.get(child)||0)+1)}return [...children].map(([path,count])=>({path,count,depth:path.split('/').length-1})).sort((a,b)=>a.path.localeCompare(b.path,'zh-CN'))})
const directoryAffectedNotes=computed(()=>notesStore.notes.filter(note=>itemMap.value.get(note.uid)?.sourcePath?.startsWith(`${sourceDir.value}/`)||itemMap.value.get(note.uid)?.sourceDir===sourceDir.value))
async function saveDirectoryNode(){if(!sourceDir.value)return;const root=itemMap.value.get(directoryAffectedNotes.value[0]?.uid)?.sourceRoot,saved=await service.value.saveSourceNode({path:sourceDir.value,sourceRoot:root,role:nodeDraft.value.role,areaUid:nodeDraft.value.areaUid||undefined,projectUid:nodeDraft.value.projectUid||undefined,childStrategy:nodeDraft.value.childStrategy,journalPattern:nodeDraft.value.journalPattern.trim()||'工作日志'}),index=sourceNodes.value.findIndex(value=>value.path===saved.path);if(index>=0)sourceNodes.value[index]=saved;else sourceNodes.value.push(saved);message.value='目录治理配置已保存'}
const affectedNoteUids=computed(()=>new Set(directoryAffectedNotes.value.map(note=>note.uid)))
const directoryPreviewStats=computed(()=>{const taskRows=candidates.value.filter(value=>affectedNoteUids.value.has(value.noteUid)&&value.state==='pending'),attachments=directoryPreviewAttachments.value.filter(value=>value.noteUid&&affectedNoteUids.value.has(value.noteUid)),remoteImages=directoryAffectedNotes.value.flatMap(note=>findMarkdownImages(note.content||'').filter(value=>value.kind==='remote'));return{taskCandidates:taskRows.length,openTasks:taskRows.filter(value=>!value.completed).length,completedTasks:taskRows.filter(value=>value.completed).length,attachments:attachments.length,images:attachments.filter(value=>value.role==='image'||value.mediaType?.startsWith('image/')).length,audio:attachments.filter(value=>value.role==='audio'||value.mediaType?.startsWith('audio/')).length,files:attachments.filter(value=>!value.mediaType?.startsWith('image/')&&!value.mediaType?.startsWith('audio/')).length,remoteImages:remoteImages.length}})
function childImpact(path:string){const notes=directoryAffectedNotes.value.filter(note=>itemMap.value.get(note.uid)?.sourcePath?.startsWith(`${path}/`)),uids=new Set(notes.map(note=>note.uid));return{notes:notes.length,tasks:candidates.value.filter(value=>uids.has(value.noteUid)&&value.state==='pending').length,attachments:directoryPreviewAttachments.value.filter(value=>value.noteUid&&uids.has(value.noteUid)).length}}
async function openDirectoryPreview(){if(nodeDraft.value.role==='project_collection'&&nodeDraft.value.childStrategy==='direct_projects'&&!nodeDraft.value.areaUid){message.value='请先选择项目所属领域';return}if(nodeDraft.value.role==='project_collection'&&nodeDraft.value.childStrategy==='direct_projects'&&!directSourceChildren.value.length){message.value='没有找到直接子项目目录，请确认选择的是项目集合的父目录';return}directoryProgress.value={running:false,percent:0,stage:'等待确认',processed:0,total:directoryAffectedNotes.value.length,error:''};directoryPreviewOpen.value=true;directoryPreviewLoading.value=true;try{directoryPreviewAttachments.value=(await attachmentLibrary({page:1,size:100000})).items}catch{directoryPreviewAttachments.value=[]}finally{directoryPreviewLoading.value=false}}
async function executeDirectoryPreview(){if(directoryProgress.value.running)return;const before=new Map(directoryAffectedNotes.value.map(note=>[note.uid,note.updatedAt]));directoryExecutionApproved.value=true;directoryProgress.value={running:true,percent:6,stage:'正在匹配已有项目…',processed:0,total:directoryAffectedNotes.value.length,error:''};const timer=window.setInterval(()=>{const processed=directoryAffectedNotes.value.filter(note=>before.get(note.uid)!==note.updatedAt).length;directoryProgress.value.processed=processed;directoryProgress.value.stage=processed?'正在关联领域、项目和内容角色…':'正在创建或复用项目…';directoryProgress.value.percent=Math.min(92,10+(processed/Math.max(1,directoryProgress.value.total))*82)},180);try{await applyDirectoryNode();if(message.value.includes('失败'))throw new Error(message.value);directoryProgress.value={...directoryProgress.value,running:false,percent:100,processed:directoryProgress.value.total,stage:'目录治理完成'}}catch(source){directoryProgress.value={...directoryProgress.value,running:false,stage:'执行失败',error:source instanceof Error?source.message:'目录治理失败'}}finally{window.clearInterval(timer)}}
async function applyDirectoryNode(){if(!sourceDir.value)return;const draft=nodeDraft.value;if(draft.role==='project_collection'&&draft.childStrategy==='direct_projects'&&!draft.areaUid){message.value='请先选择项目所属领域';return}const children=draft.role==='project_collection'&&draft.childStrategy==='direct_projects'?directSourceChildren.value:[];if(draft.role==='project_collection'&&draft.childStrategy==='direct_projects'&&!children.length){message.value='没有从该目录的原始来源路径中找到直接子项目目录，请确认选择的是项目集合的父目录';return}const preview=children.length?`将识别 ${children.length} 个项目目录：\n${children.map(value=>`• ${value.path.split('/').at(-1)}（${value.count} 篇）`).join('\n')}\n共处理 ${directoryAffectedNotes.value.length} 篇笔记。`:`将处理目录下 ${directoryAffectedNotes.value.length} 篇笔记。`;if(!await confirmDialog({title:'执行目录治理？',message:`${preview}\n工作日志目录名称：${draft.journalPattern||'工作日志'}\n原始文件不会被修改。`,confirmText:'确认执行'}))return;busy.value=true;try{await saveDirectoryNode();const changes:GovernanceBatch['changes']=[],createdNames:string[]=[],reusedNames:string[]=[];if(children.length){for(const child of children){const name=child.path.split('/').at(-1)||'未命名项目';let project=projects.value.find(value=>value.areaUid===draft.areaUid&&value.name.trim().toLocaleLowerCase()===name.trim().toLocaleLowerCase());if(project)reusedNames.push(name);else{project=await workspaceService.createProject({areaUid:draft.areaUid,name,status:'active',progressMode:'task',sortOrder:projects.value.length});createdNames.push(name);projects.value.push(project)}if(!project?.uid)throw new Error(`项目“${name}”创建后未返回有效标识`);await service.value.saveSourceNode({path:child.path,sourceRoot:itemMap.value.get(directoryAffectedNotes.value[0]?.uid)?.sourceRoot,role:'project',areaUid:draft.areaUid,projectUid:project.uid,childStrategy:'none',journalPattern:draft.journalPattern||'工作日志'});const childNotes=directoryAffectedNotes.value.filter(note=>itemMap.value.get(note.uid)?.sourcePath?.startsWith(`${child.path}/`));for(const note of childNotes){const path=itemMap.value.get(note.uid)?.sourcePath||'',journal=path.split('/').includes(draft.journalPattern||'工作日志'),after={areaUid:draft.areaUid,projectUid:project.uid,organizationStatus:'in_progress' as const};changes.push({noteUid:note.uid,before:{areaUid:note.areaUid,projectUid:note.projectUid,organizationStatus:note.organizationStatus},after,beforeRole:itemMap.value.get(note.uid)?.role,afterRole:journal?'journal':'project'});await notesStore.updateEntity(note,after);await service.value.setRole([note.uid],journal?'journal':'project')}}}else{const project=projects.value.find(value=>value.uid===draft.projectUid),areaUid=draft.areaUid||project?.areaUid;for(const note of directoryAffectedNotes.value){const after={areaUid:areaUid||note.areaUid,projectUid:draft.projectUid||note.projectUid,organizationStatus:'in_progress' as const};changes.push({noteUid:note.uid,before:{areaUid:note.areaUid,projectUid:note.projectUid,organizationStatus:note.organizationStatus},after,beforeRole:itemMap.value.get(note.uid)?.role,afterRole:draft.role});await notesStore.updateEntity(note,after);await service.value.setRole([note.uid],draft.role)}}if(changes.length)await service.value.recordBatch(`目录治理：${sourceDir.value}`,changes);window.dispatchEvent(new CustomEvent('note-flow:workspace-change'));await reload();message.value=`目录治理完成：处理 ${changes.length} 篇笔记${createdNames.length?`；新建项目 ${createdNames.length} 个（${createdNames.join('、')}）`:''}${reusedNames.length?`；复用项目 ${reusedNames.length} 个（${reusedNames.join('、')}）`:''}`;}catch(source){message.value=source instanceof Error?source.message:'目录治理失败'}finally{busy.value=false}}
function openQuality(issue:GovernanceIssue){queue.value=issue;selected.value=[]}
async function updateSelected(label:string,changes:Partial<NoteEntity>,role?:GovernanceRole){const targets=notesStore.notes.filter(note=>selected.value.includes(note.uid));if(!targets.length)return;busy.value=true;try{const audit=targets.map(note=>({noteUid:note.uid,before:Object.fromEntries(Object.keys(changes).map(key=>[key,(note as any)[key]])),after:changes,beforeRole:role?itemMap.value.get(note.uid)?.role:undefined,afterRole:role}));for(const note of targets)await notesStore.updateEntity(note,changes);if(role)await service.value.setRole(targets.map(note=>note.uid),role);await service.value.recordBatch(label,audit);message.value=`已处理 ${targets.length} 篇笔记`;await reload()}finally{busy.value=false}}
async function setRole(role:GovernanceRole){const type=role==='knowledge'?'knowledge':role==='journal'?'journal':undefined;await updateSelected(`设为${roleLabels[role]}`,{organizationStatus:'in_progress',...(type?{type}:{})},role)}
async function convertCandidate(candidate:TaskCandidate){const note=notesStore.notes.find(value=>value.uid===candidate.noteUid);if(!note)return;busy.value=true;try{const task=await tasksService.create({title:candidate.title,description:`来自笔记：${note.title}`,completed:candidate.completed,completedAt:candidate.completed?new Date().toISOString():null,areaUid:note.areaUid,projectUid:note.projectUid,listName:'治理候选',priority:0,reminderOffsetsMinutes:[]});await taskNotesService.link(task.uid,note.uid,'source');await service.value.setCandidate(candidate.uid,'converted',task.uid);message.value=`已创建任务「${candidate.title}」`;await reload()}finally{busy.value=false}}
async function ignoreCandidate(candidate:TaskCandidate){await service.value.setCandidate(candidate.uid,'ignored');await reload()}
async function ignoreCurrentIssue(issue:GovernanceIssue){if(!activeNote.value)return;await service.value.ignoreIssue(activeNote.value.uid,issue);await reload()}
async function saveRule(){if(!ruleDraft.value.name.trim()||!ruleDraft.value.pathPattern.trim())return;await service.value.saveRule({name:ruleDraft.value.name.trim(),pathPattern:ruleDraft.value.pathPattern.trim(),actions:{role:ruleDraft.value.role,noteType:ruleDraft.value.noteType||undefined,organizationStatus:ruleDraft.value.status},autoRun:ruleDraft.value.autoRun});ruleDraft.value={name:'',pathPattern:'**',role:'knowledge',noteType:'',status:'organized',autoRun:false};await reload()}
async function runRule(rule:GovernanceRule,automatic=false){const targets=previewRule(rule);if(!targets.length){message.value='该规则没有匹配笔记';return}if(!automatic&&!await confirmDialog({title:'运行治理规则？',message:`“${rule.name}”将处理 ${targets.length} 篇笔记，操作可在历史中撤销。`,confirmText:'运行规则'}))return;selected.value=targets.map(note=>note.uid);const {role,noteType,...changes}=rule.actions;await updateSelected(`规则：${rule.name}`,{...changes,...(noteType?{type:noteType}:{})},role)}
async function removeRule(rule:GovernanceRule){if(await confirmDialog({title:'删除规则？',message:`将删除“${rule.name}”，不会回退此前处理结果。`,tone:'danger',confirmText:'删除'})){await service.value.removeRule(rule.uid);await reload()}}
async function undo(batch:GovernanceBatch){if(batch.undoneAt||!await confirmDialog({title:'撤销治理批次？',message:`将恢复“${batch.label}”涉及的 ${batch.changes.length} 篇笔记。`,confirmText:'确认撤销'}))return;for(const change of batch.changes){const note=notesStore.notes.find(value=>value.uid===change.noteUid);if(note)await notesStore.updateEntity(note,change.before);if(change.beforeRole)await service.value.setRole([change.noteUid],change.beforeRole)}await service.value.markUndone(batch.uid);await reload()}
async function aiSuggest(){const note=activeNote.value;if(!note)return;if(!navigator.onLine){message.value='AI 建议需要联网';return}if(!await confirmDialog({title:'获取 AI 整理建议？',message:AI_DATA_CONFIRMATION,confirmText:'继续'}))return;busy.value=true;try{const result=await noteOrganizationService.suggestions(note.uid);if(!result.available){message.value=result.message||AI_UNAVAILABLE_MESSAGE;return}const detail=[result.summary&&`摘要：${result.summary}`,result.folderHint&&`目录：${result.folderHint}`,result.tags?.length&&`标签：${result.tags.join('、')}`].filter(Boolean).join('\n');message.value=detail||'AI 没有返回建议';if(result.summary&&await confirmDialog({title:'应用 AI 摘要建议？',message:detail,confirmText:'应用摘要'}))await updateSelected('应用 AI 建议',{summary:String(result.summary)})}catch(source){message.value=source instanceof Error?source.message:'AI 建议失败'}finally{busy.value=false}}
async function inspectDuplicates(){const note=activeNote.value;if(!note||!navigator.onLine){message.value='内容相似度复核需要联网';return}busy.value=true;try{const rows=await noteOrganizationService.duplicates(note.uid);if(!rows.length){message.value='服务端内容相似度复核未发现重复笔记';return}const chosen=await promptDialog({title:'内容相似度复核',message:rows.map((item,index)=>`${index+1}. ${item.title} · ${Math.round(item.score*100)}% · ${item.reason}`).join('\n'),inputLabel:'输入要合并的候选序号；留空则仅查看',inputPlaceholder:'例如：1',confirmText:'选择候选'}),candidate=rows[Number(chosen)-1],source=candidate&&notesStore.notes.find(item=>item.uid===candidate.uid);if(!source)return;const content=await promptDialog({title:'确认合并正文',message:`保留“${note.title}”，来源笔记“${source.title}”将在确认后进入回收站。`,inputLabel:'合并后的 Markdown 正文',inputValue:`${note.content||''}\n\n---\n\n${source.content||''}`,multiline:true,confirmText:'继续'});if(content==null||!await confirmDialog({title:'确认合并笔记？',message:`此操作将保留“${note.title}”并把“${source.title}”移入回收站。`,tone:'danger',confirmText:'确认合并'}))return;const saved=await noteOrganizationService.merge({sourceUid:source.uid,targetUid:note.uid,sourceVersion:source.version,targetVersion:note.version,title:note.title,content,summary:note.summary});await notesStore.acceptServer(saved);await notesStore.loadTrash();message.value='合并完成，来源笔记已进入回收站';await reload()}catch(source){message.value=source instanceof Error?source.message:'重复内容复核失败'}finally{busy.value=false}}
async function extractKnowledge(){if(!knowledgeAvailable)return;const note=activeNote.value;if(!note||!navigator.onLine){message.value='知识提炼需要联网';return}if(!await confirmDialog({title:'提炼为知识笔记？',message:AI_KNOWLEDGE_CONFIRMATION,confirmText:'生成草稿'}))return;busy.value=true;try{const draft=await noteOrganizationService.knowledgeDraft(note.uid),title=await promptDialog({title:'知识笔记标题',inputLabel:'标题',inputValue:String(draft.knowledgeTitle||`${note.title} · 知识整理`),confirmText:'下一步'});if(!title?.trim())return;const content=await promptDialog({title:'确认知识笔记正文',inputLabel:'Markdown 正文',inputValue:String(draft.knowledgeBody||''),multiline:true,confirmText:'创建笔记'});if(content==null)return;const created=await noteOrganizationService.createKnowledge(note.uid,{title:title.trim(),content,summary:String(draft.summary||'')});await notesStore.acceptServer(created);await service.value.register(created,{sourceType:'knowledge_extraction',role:'knowledge'});message.value='知识笔记已创建，并建立来源关系';await reload()}catch(source){message.value=source instanceof Error?source.message:'知识提炼失败'}finally{busy.value=false}}
function openNote(){if(activeNote.value)router.push({path:'/notes',query:{note:activeNote.value.uid}})}

onMounted(async()=>{await reload(true);if(typeof route.query.note==='string'&&notesStore.notes.some(note=>note.uid===route.query.note))selected.value=[route.query.note];for(const rule of rules.value.filter(value=>value.enabled&&value.autoRun)){const matches=previewRule(rule).filter(note=>itemMap.value.get(note.uid)?.role==='unclassified');if(matches.length){selected.value=matches.map(note=>note.uid);await runRule(rule,true)}}})
watch(sourceDir,path=>{if(path)selectSourceDirectory(path)})
watch([query,queue,sourceDir],()=>{visibleNoteLimit.value=notePageSize})
</script>

<template>
  <section class="governance-page">
    <header class="governance-head compact-tool-head"><div><h1>数据治理</h1><p>待治理 {{issueMetrics.find(value=>value.issue==='pending')?.count||0}} · 质量问题 {{qualityMetrics.reduce((total,value)=>total+value.count,0)}} · 健康度 {{qualityScore}}</p></div><nav><button :class="{active:tab==='workbench'}" @click="tab='workbench'">治理工作台</button><button :class="{active:tab==='quality'}" @click="tab='quality';openQuality('unclassified')">质量检查</button><button :class="{active:tab==='resources'}" @click="tab='resources'">外链资源</button><button :class="{active:tab==='rules'}" @click="tab='rules'">规则中心</button><button :class="{active:tab==='history'}" @click="tab='history'">执行历史</button></nav></header>
    <p v-if="message" class="governance-message">{{message}}</p>
    <div v-if="tab==='workbench'" class="governance-workbench">
      <div class="governance-model-hint">治理维度：内容类型 · 领域/项目/目录归属 · 整理状态（彼此独立，可组合）</div>
      <div v-if="selected.length" class="governance-selection-hint">已选择 {{selected.length}} 篇笔记；右侧操作将按所选笔记批量执行，未修改字段保持原值。</div>
      <div v-if="selected.length" class="governance-batch-toolbar"><strong>批量操作</strong><button @click="updateSelected('批量标记处理中',{organizationStatus:'in_progress'})">标记处理中</button><button class="primary" @click="updateSelected('批量整理完成',{organizationStatus:'organized',organizedAt:new Date().toISOString()})">标记已整理</button><button v-if="knowledgeAvailable" @click="extractKnowledge">提炼为知识</button><button @click="selected=[]">取消选择</button></div>
      <div v-if="filteredNotes.length>notePageSize" class="governance-page-status"><span>已显示 {{visibleNotes.length}} / {{filteredNotes.length}} 篇</span><button v-if="hasMoreVisibleNotes" @click="loadMoreVisibleNotes">再加载 {{Math.min(notePageSize,filteredNotes.length-visibleNotes.length)}} 篇</button></div>
      <aside class="governance-queues"><label><span>⌕</span><input v-model="query" placeholder="搜索标题或来源路径" /></label><h3>治理队列</h3><button @click="queue='all'"><span>全部笔记</span><b>{{notesStore.notes.length}}</b></button><button v-for="metric in issueMetrics" :key="metric.issue" :class="{active:queue===metric.issue}" @click="queue=metric.issue"><span>{{metric.label}}</span><b>{{metric.count}}</b></button><h3>来源目录</h3><div v-for="dir in visibleSourceDirs" :key="dir.path" class="governance-tree-row" :class="{active:queue==='source'&&sourceDir===dir.path}" :style="{paddingLeft:`${4+dir.depth*12}px`}"><button class="tree-toggle" :class="{hidden:!sourceDirHasChildren(dir.path)}" :title="collapsedSourceDirs.has(dir.path)?'展开目录':'收起目录'" @click.stop="toggleSourceDir(dir.path)">{{collapsedSourceDirs.has(dir.path)?'›':'⌄'}}</button><button class="tree-label" @click="queue='source';sourceDir=dir.path"><span>{{dir.path.split('/').at(-1)}}</span><b>{{dir.count}}</b></button></div><p v-if="!sourceDirs.length">暂无来源目录；普通笔记仍可按质量问题治理。</p></aside>
      <main class="governance-list"><header><div><strong>{{queue==='source'?sourceDir:queue==='all'?'全部笔记':issueLabels[queue]}}</strong><small>{{visibleNotes.length}} 篇</small></div><button @click="selectVisible">{{selected.length===visibleNotes.length?'取消全选':'全选'}}</button></header><button v-for="note in visibleNotes" :key="note.uid" class="governance-note" :class="{selected:selected.includes(note.uid)}" @click="choose(note.uid,$event)"><i>{{selected.includes(note.uid)?'✓':''}}</i><span><strong>{{note.title||'未命名笔记'}}</strong><small>{{itemMap.get(note.uid)?.sourcePath||note.captureSource||'日常创建'}}</small><em><b v-for="issue in noteIssues(note).slice(0,3)" :key="issue">{{issueLabels[issue]}}</b></em></span><time>{{note.updatedAt?new Date(note.updatedAt).toLocaleDateString('zh-CN'):''}}</time></button><p v-if="!visibleNotes.length" class="governance-empty">当前队列已经清理完成</p></main>
      <aside class="governance-inspector"><template v-if="activeNote"><header><small>当前选择 {{selected.length||1}} 篇</small><h2>{{activeNote.title||'未命名笔记'}}</h2><p>{{itemMap.get(activeNote.uid)?.sourcePath||'没有来源路径'}}</p></header><section><h3>目录角色</h3><div class="governance-role-grid"><button v-for="(label,role) in roleLabels" :key="role" :class="{active:itemMap.get(activeNote.uid)?.role===role}" @click="selected.length||choose(activeNote.uid);setRole(role)">{{label}}</button></div></section><section><h3>整理状态</h3><div class="governance-actions"><button @click="selected.length||choose(activeNote.uid);updateSelected('开始治理',{organizationStatus:'in_progress'})">处理中</button><button class="primary" @click="selected.length||choose(activeNote.uid);updateSelected('治理完成',{organizationStatus:'organized',organizedAt:new Date().toISOString()})">整理完成</button><button @click="selected.length||choose(activeNote.uid);updateSelected('忽略治理',{organizationStatus:'ignored'})">忽略</button></div></section><section><h3>任务候选 <b>{{activeCandidates.length}}</b></h3><article v-for="candidate in activeCandidates" :key="candidate.uid" class="governance-candidate"><span><strong>{{candidate.title}}</strong><small>第 {{candidate.lineIndex+1}} 行 · {{candidate.completed?'已完成':'未完成'}}</small></span><button @click="convertCandidate(candidate)">转任务</button><button @click="ignoreCandidate(candidate)">忽略</button></article><p v-if="!activeCandidates.length">没有待处理的 Checklist</p></section><section><h3>质量问题</h3><div class="governance-issue-row" v-for="issue in noteIssues(activeNote)" :key="issue"><span>{{issueLabels[issue]}}</span><button @click="ignoreCurrentIssue(issue)">忽略此项</button></div><button class="governance-wide-action" @click="inspectDuplicates">内容相似度复核与合并</button></section><section><h3>知识沉淀</h3><p>从当前项目记录生成长期知识笔记，并保留来源关系。</p><button class="governance-wide-action" v-if="knowledgeAvailable" @click="extractKnowledge">提炼为知识笔记</button></section><footer><button @click="openNote">打开原笔记</button><button @click="aiSuggest">AI 整理建议</button></footer></template><p v-else class="governance-empty">选择一篇笔记开始治理</p></aside>
      <section v-if="queue==='source'&&sourceDir" class="directory-governance-panel"><header><small>目录节点治理</small><h2>{{sourceDir.split('/').at(-1)}}</h2><p>{{sourceDir}}</p></header><label>这个目录代表<select v-model="nodeDraft.role"><option v-for="(label,role) in roleLabels" :key="role" :value="role">{{label}}</option></select></label><label>所属领域<select v-model="nodeDraft.areaUid" @change="nodeDraft.projectUid=''"><option value="">暂不设置</option><option v-for="area in areas" :key="area.uid" :value="area.uid">{{area.name}}</option></select></label><label v-if="nodeDraft.role==='project'">绑定迹语项目<select v-model="nodeDraft.projectUid"><option value="">暂不绑定</option><option v-for="project in projects.filter(value=>!nodeDraft.areaUid||value.areaUid===nodeDraft.areaUid)" :key="project.uid" :value="project.uid">{{project.name}}</option></select></label><label v-if="nodeDraft.role==='project_collection'" class="directory-check"><input v-model="nodeDraft.childStrategy" type="checkbox" true-value="direct_projects" false-value="none" /> 直接子目录分别代表一个项目</label><label v-if="nodeDraft.role==='project_collection'||nodeDraft.role==='project'">项目日志目录名称<input v-model.trim="nodeDraft.journalPattern" placeholder="工作日志" /></label><section class="directory-preview"><strong>执行预览</strong><span v-if="nodeDraft.role==='project_collection'&&nodeDraft.childStrategy==='direct_projects'">识别项目目录 {{directSourceChildren.length}} 个</span><span>影响笔记 {{directoryAffectedNotes.length}} 篇</span><span>原始文件不会修改</span></section><footer><button @click="saveDirectoryNode">仅保存配置</button><button class="primary" @click="openDirectoryPreview">预览并执行</button></footer></section>
    </div>
    <div v-else-if="tab==='quality'" class="quality-page">
      <section class="quality-overview"><article class="quality-score"><span><strong>{{qualityScore}}</strong><small>/ 100</small></span><div><h2>{{knowledgeAvailable?'知识库健康度':'资料健康度'}}</h2><p>{{qualityScore>=90?'整体状态良好，继续处理少量遗留问题。':qualityScore>=60?'存在一些结构与质量问题，建议按影响数量处理。':'需要集中治理，优先处理分类、重复和失效内容。'}}</p></div></article><article v-for="metric in qualityMetrics" :key="metric.issue" :class="{active:queue===metric.issue}" @click="openQuality(metric.issue)"><small>{{metric.label}}</small><strong>{{metric.count}}</strong><span>{{metric.count?'需要检查':'状态良好'}}</span></article></section>
      <section class="quality-content">
        <aside class="quality-categories"><header><h2>专项检查</h2><p>选择问题类型查看检测结果与依据。</p></header><button v-for="metric in qualityMetrics" :key="metric.issue" :class="{active:queue===metric.issue}" @click="openQuality(metric.issue)"><span><b>{{metric.label}}</b><small>{{qualityReason[metric.issue]}}</small></span><strong>{{metric.count}}</strong></button></aside>
        <main class="quality-results"><header><span><h2>{{queue==='all'||queue==='source'?'全部质量问题':issueLabels[queue]}}</h2><p>{{queue==='all'||queue==='source'?'选择左侧专项开始检查':qualityReason[queue]}}</p></span><label><span>⌕</span><input v-model="query" placeholder="搜索检测结果" /></label></header><button v-for="note in visibleNotes" :key="note.uid" :class="{active:activeNote?.uid===note.uid}" @click="choose(note.uid)"><span><strong>{{note.title||'未命名笔记'}}</strong><small>{{itemMap.get(note.uid)?.sourcePath||note.captureSource||'日常创建'}}</small><em><b v-for="issue in noteIssues(note).filter(value=>value!=='pending')" :key="issue">{{issueLabels[issue]}}</b></em></span><time>{{note.updatedAt?new Date(note.updatedAt).toLocaleDateString('zh-CN'):''}}</time></button><p v-if="!visibleNotes.length" class="governance-empty">该专项没有发现问题</p></main>
        <aside class="quality-detail"><template v-if="activeNote"><header><small>检测详情</small><h2>{{activeNote.title||'未命名笔记'}}</h2><p>{{itemMap.get(activeNote.uid)?.sourcePath||'没有来源路径'}}</p></header><section><h3>发现的问题</h3><article v-for="issue in noteIssues(activeNote).filter(value=>value!=='pending')" :key="issue"><span><b>{{issueLabels[issue]}}</b><small>{{qualityReason[issue]}}</small></span><button @click="ignoreCurrentIssue(issue)">忽略</button></article></section><section v-if="noteIssues(activeNote).includes('duplicate_title')"><h3>重复内容</h3><p>同名仅用于本地初筛，继续使用内容相似度进行可靠复核。</p><button class="primary" @click="inspectDuplicates">内容相似度复核</button></section><section v-if="noteIssues(activeNote).includes('task_candidates')"><h3>任务候选</h3><article v-for="candidate in activeCandidates" :key="candidate.uid"><span><b>{{candidate.title}}</b><small>第 {{candidate.lineIndex+1}} 行</small></span><button @click="convertCandidate(candidate)">转任务</button></article></section><footer><button @click="openNote">打开原笔记</button><button @click="aiSuggest">AI 辅助判断</button></footer></template><p v-else class="governance-empty">选择一条检测结果查看依据</p></aside>
      </section>
    </div>
    <div v-else-if="tab==='resources'" class="resource-governance">
      <header><div><small>EXTERNAL RESOURCES</small><h2>外链图片治理</h2><p>扫描笔记与知识，把图床图片保存为各自关联的私有附件；失败时保留原始链接。</p></div><section><article><small>待转换外链</small><strong>{{remoteImages.length}}</strong></article><article><small>涉及内容</small><strong>{{new Set(remoteImages.map(value=>`${value.entityType}:${value.entityUid}`)).size}}</strong></article><article><small>来源域名</small><strong>{{remoteHosts.length}}</strong></article></section></header>
      <div class="resource-toolbar"><label>⌕ <input v-model="resourceQuery" placeholder="搜索笔记、来源路径或图片地址" /></label><select v-model="resourceHost"><option value="">全部域名</option><option v-for="host in remoteHosts" :key="host" :value="host">{{host}}</option></select><ElButton :disabled="resourceBusy||!filteredRemoteImages.length" title="仅选择当前筛选结果中的前500条，替换此前选择" @click="selectRemoteVisible">{{remoteBatchSelected?'取消当前选择':filteredRemoteImages.length>REMOTE_IMAGE_BATCH_LIMIT?`选择前${REMOTE_IMAGE_BATCH_LIMIT}条`:'选择当前结果'}}</ElButton><ElButton :disabled="resourceBusy||!resourceSelected.size" @click="resourceSelected=new Set()">清空选择</ElButton><span class="resource-selection-count" role="status">已选 {{resourceSelected.size}} / {{REMOTE_IMAGE_BATCH_LIMIT}} 条 · 当前结果 {{filteredRemoteImages.length}} 条</span><button class="primary" :disabled="!resourceSelected.size||resourceBusy" @click="executeRemoteGovernance">{{resourceBusy?'正在转换…':`转为私有附件（${resourceSelected.size}）`}}</button></div>
      <div v-if="resourceBusy" class="resource-progress"><i :style="{width:`${resourceProgress.total?resourceProgress.completed/resourceProgress.total*100:0}%`}"/><span>正在下载并替换 {{resourceProgress.completed}} / {{resourceProgress.total}}</span></div>
      <section v-if="resourceResult" class="resource-result" :class="{failed:resourceResult.failed}"><div><strong>转换结果</strong><span>成功 {{resourceResult.converted}} · 失败 {{resourceResult.failed}} · 更新笔记 {{resourceResult.updatedNotes}}</span></div><button v-if="resourceResult.failed" @click="retryRemoteFailures">选择失败项重试</button></section>
      <section v-if="resourceResult?.failures.length" class="resource-failures"><article v-for="failure in resourceResult.failures" :key="`${failure.candidateUid}:${failure.reason}`"><span><b>{{failure.noteTitle}}</b><small>{{failure.url}}</small></span><em>{{failure.reason}}</em></article></section>
      <main class="resource-list"><article v-for="candidate in filteredRemoteImages" :key="candidate.uid" :class="{selected:resourceSelected.has(candidate.uid)}"><input type="checkbox" :checked="resourceSelected.has(candidate.uid)" :disabled="resourceBusy||(!resourceSelected.has(candidate.uid)&&resourceSelected.size>=REMOTE_IMAGE_BATCH_LIMIT)" @change="toggleRemote(candidate.uid,($event.target as HTMLInputElement).checked)"/><span><b>{{candidate.entityTitle}}</b><small>{{candidate.entityType==='knowledge'?'知识':itemMap.get(candidate.entityUid)?.sourcePath||'笔记'}} · {{candidate.alt||'无图片说明'}}</small><code>{{candidate.url}}</code></span><em>{{candidate.host}}</em></article><p v-if="!filteredRemoteImages.length" class="governance-empty">没有发现需要治理的远程图片</p></main>
    </div>
    <div v-else-if="tab==='rules'" class="governance-rules"><section><h2>新建路径规则</h2><p>先预览匹配范围，再手动运行；开启自动执行后，仅处理尚未整理的匹配笔记。</p><label>规则名称<input v-model="ruleDraft.name" placeholder="例如：项目日志目录" /></label><label>路径模式<input v-model="ruleDraft.pathPattern" placeholder="工作/**/项目日志/*.md" /></label><div><label>目录角色<select v-model="ruleDraft.role"><option v-for="(label,role) in roleLabels" :key="role" :value="role">{{label}}</option></select></label><label>笔记类型<select v-model="ruleDraft.noteType"><option value="">不修改</option><option v-for="(label,type) in noteTypeLabels" :key="type" :value="type">{{label}}</option></select></label><label>整理状态<select v-model="ruleDraft.status"><option value="pending">待整理</option><option value="in_progress">处理中</option><option value="organized">已整理</option><option value="ignored">忽略</option></select></label></div><label class="governance-check"><input v-model="ruleDraft.autoRun" type="checkbox" /> 后续自动执行</label><button class="primary" @click="saveRule">保存规则</button></section><main><article v-for="rule in rules" :key="rule.uid"><header><span><strong>{{rule.name}}</strong><small>{{rule.pathPattern}}</small></span><b>{{previewRule(rule).length}} 篇匹配</b></header><p>{{roleLabels[rule.actions.role||'unclassified']}} · {{rule.actions.noteType?noteTypeLabels[rule.actions.noteType]:'不修改类型'}} · {{rule.actions.organizationStatus||'不修改状态'}} · {{rule.autoRun?'自动执行':'手动执行'}}</p><footer><button @click="runRule(rule)">预览并运行</button><button class="danger" @click="removeRule(rule)">删除</button></footer></article><p v-if="!rules.length" class="governance-empty">还没有治理规则。建议从最稳定的一层目录开始配置。</p></main></div>
    <div v-else class="governance-history"><article v-for="batch in batches" :key="batch.uid"><span><strong>{{batch.label}}</strong><small>{{new Date(batch.createdAt).toLocaleString('zh-CN')}} · {{batch.changes.length}} 篇</small></span><b v-if="batch.undoneAt">已撤销</b><button v-else @click="undo(batch)">撤销</button></article><p v-if="!batches.length" class="governance-empty">尚无治理执行记录</p></div>
    <div v-if="directoryPreviewOpen" class="directory-execution-backdrop" @click.self="!directoryProgress.running&&(directoryPreviewOpen=false)">
      <section class="directory-execution-dialog" role="dialog" aria-modal="true">
        <header><div><small>DIRECTORY GOVERNANCE</small><h2>{{directoryProgress.running?'正在治理目录':'确认目录治理计划'}}</h2><p>{{sourceDir}}</p></div><button :disabled="directoryProgress.running" @click="directoryPreviewOpen=false">×</button></header>
        <template v-if="!directoryProgress.running&&directoryProgress.percent<100">
          <section class="execution-summary">
            <article><small>项目目录</small><strong>{{nodeDraft.role==='project_collection'&&nodeDraft.childStrategy==='direct_projects'?directSourceChildren.length:nodeDraft.projectUid?1:0}}</strong></article>
            <article><small>影响笔记</small><strong>{{directoryAffectedNotes.length}}</strong></article>
            <article><small>任务候选</small><strong>{{directoryPreviewStats.taskCandidates}}</strong><em>{{directoryPreviewStats.openTasks}} 未完成 · {{directoryPreviewStats.completedTasks}} 已完成</em></article>
            <article><small>私有附件</small><strong>{{directoryPreviewLoading?'…':directoryPreviewStats.attachments}}</strong><em>{{directoryPreviewStats.images}} 图片 · {{directoryPreviewStats.audio}} 音频 · {{directoryPreviewStats.files}} 文件</em></article>
            <article><small>远程图片</small><strong>{{directoryPreviewStats.remoteImages}}</strong><em>保留原始网络引用</em></article>
          </section>
          <p v-if="directoryPreviewLoading" class="execution-loading">正在统计任务候选与附件…</p>
          <section v-if="directSourceChildren.length" class="execution-projects"><h3>项目映射预览</h3><article v-for="child in directSourceChildren" :key="child.path"><span><b>{{child.path.split('/').at(-1)}}</b><small>{{childImpact(child.path).notes}} 篇笔记 · {{childImpact(child.path).tasks}} 个任务候选 · {{childImpact(child.path).attachments}} 个附件</small></span><em>{{projects.some(value=>value.areaUid===nodeDraft.areaUid&&value.name.trim().toLocaleLowerCase()===String(child.path.split('/').at(-1)).trim().toLocaleLowerCase())?'复用已有项目':'将新建项目'}}</em></article></section>
          <section class="execution-effects"><p>✓ 工作日志目录“{{nodeDraft.journalPattern||'工作日志'}}”将标记为日记</p><p>✓ Checklist 保留为任务候选，执行时不会直接创建任务</p><p>✓ 附件及远程图片只统计和继承笔记归属，不会重复上传</p><p>✓ 原始 Obsidian 文件不会修改</p></section>
        </template>
        <section v-else class="execution-progress"><div class="execution-progress-ring" :style="{'--progress':`${directoryProgress.percent*3.6}deg`}"><strong>{{Math.round(directoryProgress.percent)}}%</strong></div><h3>{{directoryProgress.stage}}</h3><p v-if="directoryProgress.total">已处理 {{directoryProgress.processed}} / {{directoryProgress.total}} 篇笔记</p><div><i :style="{width:`${directoryProgress.percent}%`}" /></div><p v-if="directoryProgress.error" class="execution-error">{{directoryProgress.error}}</p></section>
        <footer><button v-if="!directoryProgress.running&&directoryProgress.percent<100" @click="directoryPreviewOpen=false">返回修改</button><button v-if="!directoryProgress.running&&directoryProgress.percent<100" class="primary" :disabled="directoryPreviewLoading" @click="executeDirectoryPreview">{{directoryPreviewLoading?'正在统计…':'开始执行'}}</button><button v-if="!directoryProgress.running&&directoryProgress.percent===100" class="primary" @click="directoryPreviewOpen=false">完成</button><span v-if="directoryProgress.running">执行期间请勿关闭应用</span></footer>
      </section>
    </div>
    <ElDialog v-model="resourceDialogOpen" title="转为私有附件" width="min(680px, calc(100vw - 32px))" append-to-body :close-on-click-modal="false" :close-on-press-escape="!resourceBusy" :show-close="!resourceBusy" :before-close="done=>{if(!resourceBusy)done()}">
      <div class="resource-conversion-dialog" aria-live="polite" :aria-busy="resourceBusy">
        <template v-if="resourcePhase==='confirm'"><p>将转换 {{resourceProgress.total}} 个远程图片引用。在线时由服务器安全转存，桌面离线时进入本地附件队列。</p><p>成功后替换正文引用；失败项保留原链接。确认后请等待结果，不要重复提交。</p></template>
        <template v-else>
          <p class="resource-conversion-stage" role="status">{{resourceStage}}</p>
          <ElProgress :percentage="resourcePercent" :indeterminate="resourceBusy&&resourceProgress.completed===0" :status="resourcePhase==='error'?'exception':resourcePhase==='finished'?(resourceResult?.failed?'warning':'success'):undefined"/>
          <p>已处理 {{resourceProgress.completed}} / {{resourceProgress.total}} 个引用<span v-if="resourceBusy"> · 正在进行，请勿关闭应用</span></p>
          <ElAlert v-if="resourceError" :title="resourceError" type="error" :closable="false" show-icon/>
          <template v-if="resourceResult">
            <p>成功 {{resourceResult.converted}} · 失败 {{resourceResult.failed}} · 更新内容 {{resourceResult.updatedNotes+resourceResult.updatedKnowledge}}</p>
            <ElAlert v-if="resourceResult.failed&&!resourceResult.failures.length" title="有转换失败的图片，但服务器未返回详细原因，请检查服务端记录。" type="warning" :closable="false"/>
            <ul v-if="resourceResult.failures.length" class="resource-conversion-failures"><li v-for="(failure,index) in resourceResult.failures" :key="index"><strong>{{failure.noteTitle}}</strong><span>{{failure.url}}</span><p>{{failure.reason||'未返回具体失败原因'}}</p></li></ul>
          </template>
        </template>
      </div>
      <template #footer>
        <template v-if="resourcePhase==='confirm'"><ElButton @click="resourceDialogOpen=false">取消</ElButton><ElButton type="primary" @click="startRemoteGovernance">开始转换</ElButton></template>
        <ElButton v-else-if="resourceBusy" disabled loading>正在处理</ElButton>
        <template v-else><ElButton v-if="resourceResult?.failures.length" @click="retryRemoteFailures();resourceDialogOpen=false">选择失败项重试</ElButton><ElButton type="primary" @click="resourceDialogOpen=false">关闭</ElButton></template>
      </template>
    </ElDialog>
    <div v-if="busy&&!directoryProgress.running" class="governance-busy">正在更新治理数据…</div>
  </section>
</template>

